const grade = (output) => {
  let data;
  try { data = JSON.parse(output); }
  catch { return { pass: false, why: 'not JSON' }; }
  if (typeof data.title !== 'string')
    return { pass: false, why: 'no title' };
  if (Number.isNaN(Date.parse(data.date)))
    return { pass: false, why: 'bad date' };
  if (/as an ai/i.test(data.summary ?? ''))
    return { pass: false, why: 'forbidden phrase' };
  return { pass: true, why: 'ok' };
};

async function runEvals(cases, generate, grade, n = 5) {
  let total = 0;
  for (const c of cases) {
    let passed = 0;
    for (let i = 0; i < n; i++) {
      const out = await generate(c.input);
      if ((await grade(out, c)).pass) passed += 1;
    }
    console.log(c.id, `${passed}/${n}`);
    total += passed;
  }
  return total / (cases.length * n);
}

async function compare(cases, runA, runB, grade) {
  const tally = { win: 0, loss: 0, tie: 0 };
  for (const c of cases) {
    const a = (await grade(await runA(c.input), c)).pass;
    const b = (await grade(await runB(c.input), c)).pass;
    const r = a === b ? 'tie' : b ? 'win' : 'loss';
    tally[r] += 1;
    if (r !== 'tie') console.log(r, c.id);
  }
  return tally;
}
